const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let category=4,exam=null,reviewWrong=false,storageOK=true;
function read(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v??fallback;}catch{return fallback;}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageOK=false;notify('บันทึกในเครื่องไม่ได้ กรุณาดาวน์โหลดผลไว้');return false;}}
let history=read('axons-history-v1',[]);if(!Array.isArray(history))history=[];
let profile=read('axons-profile-v1','');if(typeof profile!=='string')profile='';
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500);}
function focusMain(){$('#main').focus();window.scrollTo(0,0);}
function nav(page){if(exam&&!exam.done){notify('กรุณาส่งคำตอบหรือออกจากชุดสอบก่อนเปลี่ยนหน้า');return;}document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='home')home();if(page==='history')historyPage();focusMain();}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>nav(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();nav('home');};
function home(){exam=null;$('#main').innerHTML=`<section class="hero"><div><div class="eyebrow">BUILD CONFIDENCE, ONE QUESTION AT A TIME</div><h1>พื้นที่ฝึกคิด ก่อนลงสนามจริง</h1><p>ฝึกตัดสินใจจากสถานการณ์ UX/UI ในงานจริง อ่านให้ครบ เลือกคำตอบที่เหมาะสมที่สุด แล้วเรียนรู้จากเหตุผล</p><div class="stats"><div><b>5</b>Competencies</div><div><b>${bank.length}</b>ข้อพร้อมเหตุผล</div><div><b>10</b>เวอร์ชันต่อหมวด</div></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"><b>↗</b></div></div></section><div class="section-head"><div><div class="eyebrow">YOUR NEXT PRACTICE</div><h2>วันนี้อยากฝึกเรื่องไหน?</h2></div><p class="muted">เลือก 1 หมวด หรือฝึกแบบรวม</p></div><div class="workspace"><section class="category-list" aria-label="เลือกหมวด">${categories.map((c,i)=>`<button class="category ${category===i?'selected':''}" data-cat="${i}" aria-pressed="${category===i}"><span class="icon">${c[2]}</span><span class="cat-text"><strong>${i+1}. ${c[0]} ${i===4?'<span class="badge">FOCUS</span>':''}</strong><small>${c[1]}</small><small>${examBlueprint[i].note}</small></span><span class="num">${bank.filter(q=>q.category===i).length} ข้อในคลัง</span></button>`).join('')}<button class="category ${category===-1?'selected':''}" data-cat="-1" aria-pressed="${category===-1}"><span class="icon">⊞</span><span class="cat-text"><strong>รวมทุก Competency</strong><small>ทบทวนทักษะจากทั้ง 5 หมวด</small></span><span class="num">${bank.length} ข้อในคลัง</span></button></section><form class="panel" id="setup"><h2>ตั้งค่าการฝึก</h2><p class="muted" style="font-size:12px">ชุดเล็ก ๆ เพื่อความเข้าใจที่มากขึ้น</p><label for="name">ชื่อผู้ฝึก / ชื่อเล่น</label><input id="name" maxlength="50" required placeholder="เช่น มายด์" value="${esc(profile)}" autocomplete="off"><div class="row"><div><label for="count">จำนวนข้อ</label><select id="count">${counts().map(n=>`<option ${n===(category===-1?10:examBlueprint[category].count)?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="version">เวอร์ชัน</label><select id="version"><option value="random">สุ่มเวอร์ชัน</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}">V${String(i+1).padStart(2,'0')}</option>`).join('')}</select></div></div><label for="mode">รูปแบบ</label><select id="mode"><option value="exam">โหมดสอบ · เฉลยหลังส่ง</option><option value="practice">โหมดฝึก · ตรวจทีละข้อได้</option></select><button class="btn full" type="submit">เริ่มทำแบบฝึก &nbsp; →</button><p class="hint">ไม่มีจับเวลา · ข้อละ 1 คะแนน<br>ไม่มีข้อซ้ำภายในชุด แต่อาจพบข้อเดิมข้ามเวอร์ชัน</p><div class="line"></div><p class="hint">ชื่อใช้แยกประวัติในเบราว์เซอร์นี้เท่านั้น ไม่ใช่บัญชีสมาชิก</p></form></div><div class="note">✦ &nbsp; เน้นหมวด 5: Persona, Journey Analysis, Product Testing, Product Feedback และ research ที่ใช้หลักฐาน · คลัง ${bankVersion} เพิ่ม 30 ข้อจาก Project Tracking, Writing System และ Website Components · แสดงที่มาหลังตรวจคำตอบ · ไม่นำจุดคลุมเครือในเอกสารมาเป็นเฉลย</div>`;
document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{const name=$('#name').value;category=Number(b.dataset.cat);profile=name;home();});$('#setup').onsubmit=e=>{e.preventDefault();const name=$('#name').value.trim();if(!name){$('#name').setCustomValidity('กรุณาระบุชื่อผู้ฝึก');$('#name').reportValidity();return;}profile=name;save('axons-profile-v1',name);const v=$('#version').value==='random'?crypto.getRandomValues(new Uint32Array(1))[0]%10+1:Number($('#version').value);exam={name,category,version:v,bankVersion,mode:$('#mode').value,questions:ExamEngine.makeSet(bank,category,Number($('#count').value),v),answers:{},checked:{},index:0,started:Date.now(),done:false};renderExam();focusMain();};$('#name').oninput=()=>$('#name').setCustomValidity('');}
function counts(){return category===4?[5,10,15,20]:category===1?[5,10,15,20,30]:category===-1?[5,10,20,30]:[5,8,10];}
function title(c){return c===-1?'รวมทุก Competency':categories[c][0];}
function renderExam(){const e=exam,q=e.questions[e.index],answered=Object.keys(e.answers).length;$('#main').innerHTML=`<div class="eyebrow">${e.mode==='exam'?'EXAM MODE · เฉลยหลังส่ง':'PRACTICE MODE'} / V${String(e.version).padStart(2,'0')}</div><h1 style="font-size:25px">${title(e.category)}</h1><p class="muted">ผู้ฝึก ${esc(e.name)} · คลัง ${e.bankVersion} · ตอบแล้ว ${answered}/${e.questions.length} ข้อ</p><div class="progress"><span style="width:${answered/e.questions.length*100}%"></span></div><div class="exam-layout"><section class="panel question"><div class="eyebrow">ข้อ ${e.index+1} / ${e.questions.length} &nbsp; · &nbsp; ${q.topic}</div><h2 id="question-title">${q.prompt}</h2><fieldset style="border:0;padding:0;margin:0" aria-labelledby="question-title"><legend class="muted" style="font-size:12px">เลือกคำตอบที่เหมาะสมที่สุดเพียงข้อเดียว</legend>${q.choices.map((a,i)=>`<label class="choice ${e.answers[q.id]===a.key?'picked':''}"><input type="radio" name="answer" value="${a.key}" ${e.answers[q.id]===a.key?'checked':''} ${e.checked[q.id]?'disabled':''}><span>${String.fromCharCode(65+i)}. ${a.text}</span></label>`).join('')}</fieldset>${e.mode==='practice'?`<button class="btn secondary" id="check" ${e.answers[q.id]===undefined||e.checked[q.id]?'disabled':''}>ตรวจข้อนี้</button>${e.checked[q.id]?explanation(q,e.answers[q.id]):''}`:''}<div class="actions"><button class="btn secondary" id="prev" ${e.index===0?'disabled':''}>← ข้อก่อนหน้า</button><button class="btn" id="next">${e.index===e.questions.length-1?'ตรวจความครบถ้วน':'ข้อถัดไป →'}</button></div><div id="confirm-slot"></div></section><section class="panel"><h3 style="margin-top:0">แผนที่ข้อสอบ</h3><div class="question-map">${e.questions.map((x,i)=>`<button class="dot ${e.answers[x.id]!==undefined?'answered':''} ${e.index===i?'current':''}" data-q="${i}" aria-label="ข้อ ${i+1}${e.answers[x.id]!==undefined?' ตอบแล้ว':''}" ${e.index===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p class="hint">พื้นเขียว = ตอบแล้ว · กรอบ = ข้อปัจจุบัน</p><button class="btn full" id="submit">ส่งคำตอบ</button><button class="btn secondary full" id="leave">ออกจากชุดสอบ</button><p class="hint">คำตอบระหว่างทำยังไม่บันทึก หากปิดหรือโหลดหน้าใหม่จะสูญหาย</p></section></div>`;
document.querySelectorAll('input[name=answer]').forEach(x=>x.onchange=()=>{e.answers[q.id]=Number(x.value);renderExam();});document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{e.index=Number(b.dataset.q);renderExam();focusMain();});$('#prev').onclick=()=>{e.index--;renderExam();focusMain();};$('#next').onclick=()=>{if(e.index<e.questions.length-1){e.index++;renderExam();focusMain();}else confirmSubmit();};$('#submit').onclick=confirmSubmit;$('#leave').onclick=()=>{const slot=$('#confirm-slot');slot.innerHTML='<div class="confirm"><h3>ออกโดยไม่บันทึกผล?</h3><p>คำตอบในรอบนี้จะหายไป</p><button class="btn" id="leave-yes">ออกจากชุดสอบ</button> <button class="btn secondary" id="cancel">ทำต่อ</button></div>';$('#leave-yes').onclick=()=>{exam=null;home();focusMain();};$('#cancel').onclick=renderExam;slot.scrollIntoView({behavior:'smooth',block:'center'});};if($('#check'))$('#check').onclick=()=>{e.checked[q.id]=true;renderExam();};}
function confirmSubmit(){const missing=exam.questions.filter(q=>exam.answers[q.id]===undefined).length;const slot=$('#confirm-slot');slot.innerHTML=`<div class="confirm"><h3>${missing?`ยังไม่ได้ตอบ ${missing} ข้อ`:'ตอบครบแล้ว พร้อมส่งคำตอบ?'}</h3><p>${missing?'ข้อที่เว้นจะได้ 0 คะแนน คุณสามารถกลับไปตอบก่อนส่งได้':'หลังส่งจะเห็นคะแนนและเหตุผลทุกข้อ'}</p><button class="btn" id="yes">ยืนยันส่งคำตอบ</button> <button class="btn secondary" id="cancel">กลับไปทำต่อ</button></div>`;$('#yes').onclick=finish;$('#cancel').onclick=renderExam;slot.scrollIntoView({behavior:'smooth',block:'center'});$('#yes').focus();}
function explanation(q,answer){return `<div class="answer-line ${answer===q.answer?'correct':'incorrect'}">${answer===q.answer?'✓ ตอบถูก':answer===undefined?'— ไม่ได้ตอบ':'✕ ยังไม่ถูก'}<br>คำตอบที่เลือก: ${answer===undefined?'ไม่ได้ตอบ':q.options[answer]}<br><b>คำตอบที่เหมาะสม: ${q.options[q.answer]}</b></div><p class="reason"><b>เหตุผล:</b> ${q.reason}</p>${sourceInfo(q)}`;}
function sourceInfo(q){if(!q.source)return '<p class="hint">ที่มา: หลักการ UX/UI ทั่วไป · โจทย์จำลอง</p>';const src=sourceCatalog[q.source.key];const url=`https://www.figma.com/design/${src.file}/?node-id=${q.source.nodeId.replace(':','-')}`;return `<p class="hint source-note">${esc(q.source.kind)} · <a href="${url}" target="_blank" rel="noopener">${src.label} ↗</a><br>อาจต้องได้รับสิทธิ์เข้าถึงไฟล์ต้นทาง</p>`;}
function finish(){if(exam.done)return;exam.done=true;exam.finished=Date.now();exam.score=ExamEngine.score(exam.questions,exam.answers);const r={id:crypto.randomUUID(),name:exam.name,category:exam.category,version:exam.version,mode:exam.mode,score:exam.score,total:exam.questions.length,date:new Date().toISOString(),bankVersion:exam.bankVersion,minutes:Math.max(1,Math.round((exam.finished-exam.started)/60000))};history.push(r);save('axons-history-v1',history);reviewWrong=false;results();focusMain();}
function results(){const e=exam,percent=Math.round(e.score/e.questions.length*100);const visible=e.questions.filter(q=>!reviewWrong||e.answers[q.id]!==q.answer);const topics=[...new Set(e.questions.map(q=>q.topic))];$('#main').innerHTML=`<section class="result-hero"><div><div class="eyebrow">PRACTICE COMPLETE</div><h1>อีกก้าวของการเรียนรู้</h1><p>${esc(e.name)} · V${String(e.version).padStart(2,'0')} · ${e.mode==='exam'?'โหมดสอบ':'โหมดฝึก'} · คลัง ${e.bankVersion}</p></div><div><div class="score">${percent}%</div><div>${e.score} / ${e.questions.length} คะแนน</div></div></section><p class="muted">คะแนนใช้สะท้อนการฝึกครั้งนี้ ไม่มีเกณฑ์ผ่านทางการ</p><div class="summary-grid">${topics.map(t=>{const qs=e.questions.filter(q=>q.topic===t);return `<div>${t}<b style="float:right">${ExamEngine.score(qs,e.answers)}/${qs.length}</b></div>`;}).join('')}</div><div class="filter"><button class="btn" id="again">เลือกชุดฝึกใหม่</button><button class="btn secondary" id="export-result">ดาวน์โหลดผล JSON</button><button class="btn secondary" id="filter">${reviewWrong?'แสดงทุกข้อ':'ดูเฉพาะข้อที่ควรทบทวน'}</button></div><h2>ทบทวนคำตอบและเหตุผล</h2><p class="hint">ข้อสอบเป็นสถานการณ์จำลอง ข้อใหม่มีลิงก์ต้นทางและป้ายแยกเกณฑ์ในเอกสารกับโจทย์ประยุกต์</p><section class="review">${visible.length?visible.map(q=>`<details open><summary><span class="${e.answers[q.id]===q.answer?'correct':'incorrect'}">${e.answers[q.id]===q.answer?'✓':'↻'}</span> ข้อ ${e.questions.indexOf(q)+1} · ${q.topic}<br>${q.prompt}</summary>${explanation(q,e.answers[q.id])}</details>`).join(''):'<div class="panel">ตอบถูกทุกข้อในชุดนี้แล้ว ลองเวอร์ชันอื่นเพื่อทบทวนต่อได้ค่ะ</div>'}</section><div class="note">${storageOK?'บันทึกผลไว้ในเบราว์เซอร์นี้แล้ว':'ไม่สามารถบันทึกในเบราว์เซอร์นี้ได้ กรุณาดาวน์โหลดผล'} · ไม่มีการส่งชื่อหรือคะแนนไปยังเซิร์ฟเวอร์</div>`;$('#again').onclick=()=>{exam=null;home();focusMain();};$('#filter').onclick=()=>{reviewWrong=!reviewWrong;results();};$('#export-result').onclick=()=>download('uxui-result.json',{name:e.name,category:title(e.category),version:e.version,bankVersion:e.bankVersion,score:e.score,total:e.questions.length,questions:e.questions.map(q=>({id:q.id,topic:q.topic,prompt:q.prompt,selected:e.answers[q.id]===undefined?null:q.options[e.answers[q.id]],correct:q.options[q.answer],reason:q.reason,source:q.source||null}))});}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function historyPage(){exam=null;const mine=history.filter(r=>r.name===profile);$('#main').innerHTML=`<div class="eyebrow">YOUR LEARNING JOURNEY</div><h1>ประวัติการฝึก</h1><p class="muted">ประวัติในเบราว์เซอร์นี้ แยกตามชื่อที่กรอก · ไม่ใช่ระบบยืนยันตัวตน</p><div class="panel" style="margin-top:24px"><label for="history-name">เลือกชื่อผู้ฝึก</label><select id="history-name"><option value="">เลือกชื่อ</option>${[...new Set(history.map(r=>r.name))].map(n=>`<option ${n===profile?'selected':''} value="${esc(n)}">${esc(n)}</option>`).join('')}</select>${mine.length?`<div class="table-wrap"><table><thead><tr><th>วันที่</th><th>หมวด</th><th>ชุด / โหมด</th><th>คะแนน</th></tr></thead><tbody>${[...mine].reverse().map(r=>`<tr><td>${new Date(r.date).toLocaleString('th-TH')}</td><td>${title(r.category)}</td><td>V${r.version} · ${r.mode==='exam'?'สอบ':'ฝึก'}<br><small>คลัง ${esc(r.bankVersion||'ก่อน 2026.11.10')}</small></td><td><b>${r.score}/${r.total}</b> (${Math.round(r.score/r.total*100)}%)</td></tr>`).join('')}</tbody></table></div><div class="filter"><button class="btn secondary" id="export-history">ดาวน์โหลดประวัติของชื่อนี้</button><button class="btn secondary" id="clear">ลบประวัติของชื่อนี้</button></div><div id="clear-slot"></div>`:'<div class="empty"><h2>ยังไม่มีประวัติสำหรับชื่อนี้</h2><p class="muted">เริ่มฝึก แล้วกลับมาดูพัฒนาการของตัวเอง</p><button class="btn" id="start-home">เลือกแบบฝึก</button></div>'}</div><div class="note">ผู้ที่ใช้เบราว์เซอร์เดียวกันสามารถเลือกดูชื่ออื่นได้ ไม่ควรกรอกข้อมูลส่วนบุคคลที่ละเอียด หากล้างข้อมูลเว็บไซต์หรือเปลี่ยนเครื่อง ประวัติจะไม่ตามไปด้วย</div>`;$('#history-name').onchange=e=>{profile=e.target.value;historyPage();};if($('#start-home'))$('#start-home').onclick=()=>nav('home');if($('#export-history'))$('#export-history').onclick=()=>download('uxui-history.json',mine);if($('#clear'))$('#clear').onclick=()=>{$('#clear-slot').innerHTML='<div class="confirm">ลบประวัติทั้งหมดของชื่อนี้ในเครื่องนี้? <button class="btn" id="clear-yes">ยืนยันลบ</button> <button class="btn secondary" id="clear-no">ยกเลิก</button></div>';$('#clear-yes').onclick=()=>{history=history.filter(r=>r.name!==profile);save('axons-history-v1',history);historyPage();};$('#clear-no').onclick=historyPage;};}
window.addEventListener('beforeunload',e=>{if(exam&&!exam.done){e.preventDefault();e.returnValue='';}});home();
